/* Keep case-level scenario buttons synchronized with the adopted selector. */
(()=>{const select=document.querySelector('#starting-point');if(!select)return;const buttons=[...document.querySelectorAll('[data-scenario-choice]')];const sync=()=>buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scenarioChoice===select.value)));buttons.forEach(b=>b.addEventListener('click',()=>{if(select.value===b.dataset.scenarioChoice)return;select.value=b.dataset.scenarioChoice;select.dispatchEvent(new Event('change',{bubbles:true}));sync()}));select.addEventListener('change',sync);window.addEventListener('popstate',()=>setTimeout(sync,0));window.addEventListener('hashchange',()=>setTimeout(sync,0));sync();select.setAttribute("tabindex","-1");select.setAttribute("aria-hidden","true");select.closest(".about-suite").classList.add("suite-choice-ready")})();

/* Section 01 uses one selected term at a time, keeping explanations brief and connected. */
(()=>{const map=document.querySelector('#model .relationship-map');if(!map)return;const notes={'Methods + standards':[['Shared method','Makes useful practice repeatable across applications.'],['Guiding standards','Keeps design and evidence choices consistent.']],'Delivery + learning':[['Delivery evidence','Retains what happened with the work.'],['Reusable knowledge','Carries selected lessons into the next application.']],'Business definitions':[['Shared language','Connects the question to agreed business meaning.'],['Decision context','Makes the intended use of analysis clear.']],'Analytical solutions':[['Applied analysis','Turns the operating method into a usable result.'],['Purposeful delivery','Connects the work to a defined business need.']],'Evidence + operation':[['Working proof','Links the result to its sources and checks.'],['Sustained use','Keeps ownership and operation visible after delivery.']],'Modules':[['Working components','Make individual parts of the application inspectable.'],['Reusable structure','Carry useful patterns into related work.']],'Case studies':[['Visible evidence','Show how the method was applied in context.'],['Retained learning','Connect results to the decisions that shaped them.']],'Playbooks':[['Repeatable guidance','Make the approach usable by another reader.'],['Practical context','Connect standards to the work they guide.']]};let active;const close=()=>{if(!active)return;active.button.setAttribute('aria-pressed','false');active.panel.hidden=true;active=undefined};const makeLane=(className,label,steps)=>{const lane=document.createElement('div');lane.className=className;const title=document.createElement('span');title.className='relationship-lane-label';title.textContent=label;const track=document.createElement('div');track.className='relationship-lane-track';steps.forEach((step,index)=>{if(index){const arrow=document.createElement('span');arrow.className='relationship-lane-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent=step.arrow}const item=document.createElement('span');item.textContent=step.label;track.append(item)});lane.append(title,track);return lane};map.prepend(makeLane('relationship-lane relationship-application-lane','Application route',[{label:'Cascadia'},{arrow:'→',label:'Cascadia Analytics'},{arrow:'→',label:'Robbins Analytics'}]));[...map.querySelectorAll('.relationship-node')].forEach((node,index)=>{const panel=document.createElement('div');panel.className='relationship-explanation';panel.id=`relationship-explanation-${index+1}`;panel.hidden=true;node.append(panel);[...node.querySelectorAll('.relationship-terms span')].forEach(term=>{const label=term.textContent.trim();const button=document.createElement('button');button.type='button';button.className='relationship-term';button.textContent=label;button.setAttribute('aria-pressed','false');button.setAttribute('aria-controls',panel.id);button.addEventListener('click',()=>{if(active&&active.button===button){close();return}close();const list=document.createElement('ul');(notes[label]||[]).forEach(([lead,copy])=>{const item=document.createElement('li');const strong=document.createElement('strong');strong.textContent=lead;item.append(strong,document.createTextNode(` — ${copy}`));list.append(item)});panel.replaceChildren(list);panel.hidden=false;button.setAttribute('aria-pressed','true');active={button,panel}});term.replaceWith(button)})});map.append(makeLane('relationship-feedback','Learning return',[{label:'Cascadia evolves'},{arrow:'←',label:'Evaluate + retain learning'},{arrow:'←',label:'Portfolio work reveals evidence'}]))})();
(()=>{document.querySelectorAll('#model .relationship-lane-track').forEach(track=>{const stops=[...track.children].filter(item=>!item.classList.contains('relationship-lane-arrow'));stops.slice(0,-1).forEach(stop=>{const arrow=document.createElement('span');arrow.className='relationship-lane-arrow';arrow.setAttribute('aria-hidden','true');arrow.textContent=track.closest('.relationship-feedback')?'←':'→';stop.after(arrow)});});})();

/* Lane titles reveal their concise reading guide; one lane guide is open at a time. */
(()=>{const guides={application:[['Cascadia','supplies the method.'],['Cascadia Analytics','applies it to analytical work.'],['Robbins Analytics','makes the work inspectable.']],learning:[['Portfolio evidence','reveals what happened.'],['Evaluation','decides what is worth retaining.'],['Cascadia','carries selected knowledge forward.']]};let active;[...document.querySelectorAll('#model .relationship-lane,#model .relationship-feedback')].forEach((lane,index)=>{const label=lane.querySelector('.relationship-lane-label');if(!label)return;const kind=lane.classList.contains('relationship-feedback')?'learning':'application';const panel=document.createElement('div');panel.className='relationship-lane-details';panel.id=`relationship-lane-details-${index+1}`;panel.hidden=true;const button=document.createElement('button');button.type='button';button.className='relationship-lane-label';button.textContent=label.textContent;button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls',panel.id);button.addEventListener('click',()=>{if(active&&active.button===button){button.setAttribute('aria-expanded','false');panel.hidden=true;active=undefined;return}if(active){active.button.setAttribute('aria-expanded','false');active.panel.hidden=true}const list=document.createElement('ul');guides[kind].forEach(([lead,copy])=>{const item=document.createElement('li');const strong=document.createElement('strong');strong.textContent=lead;item.append(strong,document.createTextNode(` ${copy}`));list.append(item)});panel.replaceChildren(list);panel.hidden=false;button.setAttribute('aria-expanded','true');active={button,panel}});label.replaceWith(button);lane.append(panel)})})();

/* Make the connector verbs explicit and keep contribution-detail punctuation compact. */
(()=>{const labels=[['Applied',' to ','data + analytics'],['visible','Made ',' through the work']];[...document.querySelectorAll('#model .relationship-edge')].forEach((edge,index)=>{const target=edge.querySelector('span:not(.relationship-arrow)');const parts=labels[index];if(!target||!parts)return;const strong=document.createElement('strong');strong.textContent=parts[0];target.replaceChildren();if(index===0){target.append(strong,document.createTextNode(parts[1]))}else{target.append(document.createTextNode(parts[1]),strong)}target.append(document.createElement('br'),document.createTextNode(parts[2]))});document.addEventListener('click',event=>{if(!event.target.closest('#model .relationship-term'))return;queueMicrotask(()=>document.querySelectorAll('#model .relationship-explanation li').forEach(item=>item.childNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE)node.textContent=node.textContent.replace(' — ',': ')})))})})();

/* Desktop reads directly from the aligned swimlane headers; compact widths retain route guides. */
(()=>{if(!matchMedia('(min-width:1100px)').matches)return;const guides={application:{'Cascadia':[['Operating method','Provides the reusable method and standards.'],['Learning base','Retains selected practice for the next application.']],'Cascadia Analytics':[['Applied system','Turns the method into data and analytics work.'],['Evidence path','Connects analytical results to their checks and operation.']],'Robbins Analytics':[['Visible portfolio','Makes applications inspectable as modules, cases and playbooks.'],['Working evidence','Shows how the approach was applied in context.']]},learning:{'Cascadia evolves':[['Selected knowledge','Strengthens the operating system for the next application.'],['Maintained method','Keeps reusable practice available across contexts.']],'Evaluate + retain learning':[['Evaluate','Distinguishes observations from knowledge worth carrying forward.'],['Retain','Links the decision and evidence to the work.']],'Portfolio work reveals evidence':[['Evidence from delivery','Shows what happened in the application.'],['Learning trigger','Supplies the observations to evaluate and retain.']]}};let active;[...document.querySelectorAll('#model .relationship-application-lane,#model .relationship-feedback')].forEach(lane=>{const kind=lane.classList.contains('relationship-feedback')?'learning':'application';const panel=lane.querySelector('.relationship-lane-details');lane.querySelectorAll('.relationship-lane-track > span:not(.relationship-lane-arrow)').forEach(stop=>{const label=stop.textContent.trim();const button=document.createElement('button');button.type='button';button.className='relationship-lane-stop';button.textContent=label;button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls',panel.id);button.addEventListener('click',()=>{if(active&&active.button===button){button.setAttribute('aria-expanded','false');panel.hidden=true;active=undefined;return}if(active){active.button.setAttribute('aria-expanded','false');active.panel.hidden=true}const list=document.createElement('ul');(guides[kind][label]||[]).forEach(([lead,copy])=>{const item=document.createElement('li');const strong=document.createElement('strong');strong.textContent=lead;item.append(strong,document.createTextNode(`: ${copy}`));list.append(item)});panel.replaceChildren(list);panel.hidden=false;button.setAttribute('aria-expanded','true');active={button,panel}});stop.replaceWith(button)})})})();

