/* Keep vertical arrows centered in their actual gaps as card details open or close. */
(()=>{const map=document.querySelector('#model .relationship-map');if(!map||!window.ResizeObserver)return;const cards=[...map.querySelectorAll('.relationship-node')];const applicationStops=[...map.querySelectorAll('.relationship-application-lane .relationship-lane-stop')];const feedbackStops=[...map.querySelectorAll('.relationship-feedback .relationship-lane-stop')];const arrowSize=()=>parseFloat(getComputedStyle(document.documentElement).fontSize);const sync=()=>{if(!matchMedia('(min-width:1100px)').matches)return;const size=arrowSize();cards.forEach((card,index)=>{const application=applicationStops[index];const feedback=feedbackStops[index];if(application){const gap=Math.max(0,card.getBoundingClientRect().top-application.getBoundingClientRect().bottom);application.style.setProperty('--relationship-application-arrow-offset',`${Math.max(0,(gap-size)/2)}px`)}if(feedback){const gap=Math.max(0,feedback.getBoundingClientRect().top-card.getBoundingClientRect().bottom);feedback.style.setProperty('--relationship-feedback-arrow-offset',`${Math.max(0,(gap-size)/2)}px`)}})};let frame;const schedule=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(sync)};const observer=new ResizeObserver(schedule);[map,...cards,...applicationStops,...feedbackStops].forEach(item=>observer.observe(item));map.addEventListener('click',()=>requestAnimationFrame(schedule));window.addEventListener('resize',schedule);sync()})();

/* One lower SVG arrow per card: open heads and a measured live length. */
(()=>{const map=document.querySelector('#model .relationship-map');if(!map||!window.ResizeObserver)return;const cards=[...map.querySelectorAll('.relationship-node')];const stops=[...map.querySelectorAll('.relationship-feedback .relationship-lane-stop')];if(cards.length!==stops.length)return;const directions=['up','both','down'];const svgNs='http://www.w3.org/2000/svg';const arrows=directions.map(direction=>{const svg=document.createElementNS(svgNs,'svg');svg.classList.add('relationship-svg-arrow');svg.dataset.direction=direction;svg.setAttribute('aria-hidden','true');map.append(svg);return svg});const shape=(svg,direction,height)=>{const line=(y1,y2)=>{const item=document.createElementNS(svgNs,'line');item.setAttribute('x1','8');item.setAttribute('x2','8');item.setAttribute('y1',String(y1));item.setAttribute('y2',String(y2));return item};const head=(points)=>{const item=document.createElementNS(svgNs,'polyline');item.setAttribute('points',points);return item};const headSize=6;const tip=1;const end=height-1;let parts;if(direction==='up')parts=[head(`4 ${headSize+tip} 8 ${tip} 12 ${headSize+tip}`),line(headSize+tip,end)];else if(direction==='down')parts=[line(tip,end-headSize),head(`4 ${end-headSize} 8 ${end} 12 ${end-headSize}`)];else parts=[head(`4 ${headSize+tip} 8 ${tip} 12 ${headSize+tip}`),line(headSize+tip,end-headSize),head(`4 ${end-headSize} 8 ${end} 12 ${end-headSize}`)];svg.setAttribute('viewBox',`0 0 16 ${height}`);svg.replaceChildren(...parts)};const sync=()=>{if(!matchMedia('(min-width:1100px)').matches){arrows.forEach(arrow=>arrow.hidden=true);return}const mapRect=map.getBoundingClientRect();cards.forEach((card,index)=>{const cardRect=card.getBoundingClientRect();const stopRect=stops[index].getBoundingClientRect();const gap=Math.max(0,stopRect.top-cardRect.bottom);const clearance=Math.min(10,Math.max(6,gap*.18));const height=Math.max(14,gap-clearance*2);const arrow=arrows[index];arrow.hidden=false;arrow.style.left=`${cardRect.left-mapRect.left+cardRect.width/2}px`;arrow.style.top=`${cardRect.bottom-mapRect.top+clearance}px`;arrow.style.height=`${height}px`;shape(arrow,directions[index],height)})};let frame;const schedule=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(sync)};const observer=new ResizeObserver(schedule);[map,...cards,...stops].forEach(item=>observer.observe(item));map.addEventListener('click',()=>requestAnimationFrame(schedule));window.addEventListener('resize',schedule);sync()})();

/* Fallback for preview surfaces without ResizeObserver; interaction events still recalculate the arrows. */
